// MMI homepage v4 installer: animations + duplicate-header fix.
// Run from your project root:  node install_homepage_v4.mjs
import fs from 'fs'
import path from 'path'
import os from 'os'

const FILES = {"Brand.tsx":"'use client'\n\nimport { useState } from 'react'\nimport Link from 'next/link'\nimport { LOGO_SRC } from './logo'\n\nexport function Logo({ light = false }: { light?: boolean }) {\n  const [bad, setBad] = useState(false)\n  return (\n    <Link href=\"/\" className=\"mh-logo\" style={light ? { color: '#fff' } : undefined} aria-label=\"MatchMyInterview home\">\n      {LOGO_SRC && !bad ? (\n        // eslint-disable-next-line @next/next/no-img-element\n        <img className=\"mh-logo-img\" src={LOGO_SRC} alt=\"\" width={32} height={32} onError={() => setBad(true)} />\n      ) : (\n        <span className=\"mh-logo-mark\">M</span>\n      )}\n      <span>MatchMyInterview</span>\n    </Link>\n  )\n}\n","FinalCTASection.tsx":"'use client'\n\nimport { ArrowRight } from 'lucide-react'\nimport { Reveal, type CtaProps } from './shared'\n\nexport default function FinalCTASection({ onAuth }: CtaProps) {\n  return (\n    <section className=\"mh-sec\">\n      <div className=\"mh-wrap\">\n        <Reveal>\n          <div className=\"mh-cta\">\n            <div className=\"mh-blob\" style={{ width: 300, height: 300, background: '#60A5FA', top: -100, left: -60 }} />\n            <div className=\"mh-blob\" style={{ width: 300, height: 300, background: '#C084FC', bottom: -120, right: -60, animationDelay: '-7s' }} />\n            <h2>Start building your proof.</h2>\n            <p>Create your profile, find a peer, and turn every interview into evidence.</p>\n            <button className=\"mh-btn mh-btn-white\" onClick={onAuth}>Build My Portfolio <ArrowRight size={18} aria-hidden=\"true\" /></button>\n          </div>\n        </Reveal>\n      </div>\n    </section>\n  )\n}\n","GuestHomepage.tsx":"'use client'\n\nimport './marketing.css'\nimport './marketing-v2.css'\nimport MarketingNav from './MarketingNav'\nimport HeroSection from './HeroSection'\nimport ResumeVsEvidenceSection from './ResumeVsEvidenceSection'\nimport ProductLoopSection from './ProductLoopSection'\nimport TwoSidedValueSection from './TwoSidedValueSection'\nimport SkillValidationSection from './SkillValidationSection'\nimport PortfolioPreviewSection from './PortfolioPreviewSection'\nimport SocialProofSection from './SocialProofSection'\nimport TalentPreviewSection from './TalentPreviewSection'\nimport FinalCTASection from './FinalCTASection'\nimport MarketingFooter from './MarketingFooter'\nimport type { CtaProps } from './shared'\n\n// users, onlineCount and coffeesShared are accepted for compatibility with page.tsx\n// but intentionally unused: the homepage no longer shows unverified stats.\ntype Props = CtaProps & {\n  users?: unknown\n  onlineCount?: number\n  coffeesShared?: number\n}\n\nexport default function GuestHomepage({ onAuth }: Props) {\n  return (\n    <div className=\"mh\">\n      <MarketingNav onAuth={onAuth} />\n      <main>\n        <HeroSection onAuth={onAuth} />\n        <ResumeVsEvidenceSection />\n        <ProductLoopSection />\n        <TwoSidedValueSection />\n        <SkillValidationSection />\n        <PortfolioPreviewSection />\n        <SocialProofSection />\n        <TalentPreviewSection />\n        <FinalCTASection onAuth={onAuth} />\n      </main>\n      <MarketingFooter />\n    </div>\n  )\n}\n","HeroSection.tsx":"'use client'\n\nimport { useEffect, useState, type ReactNode } from 'react'\nimport { AnimatePresence, motion, useReducedMotion } from 'framer-motion'\nimport { ArrowLeftRight, ArrowRight, Check, Link2 } from 'lucide-react'\nimport { careers } from './careers'\nimport { PreviewBadge, Reveal, Waveform, type CtaProps } from './shared'\n\nconst DONE = 5\n\nfunction FlowCard({ k, step, title, children }: { k: number; step: number; title: string; children: ReactNode }) {\n  const on = step >= k\n  const cur = step === k\n  return (\n    <>\n      {k > 0 && (\n        <div className=\"mh-fconn\">\n          <i style={{ height: on ? '100%' : '0%' }} />\n          {cur && <b />}\n        </div>\n      )}\n      <div className={`mh-fcard${on ? ' on' : ''}${cur ? ' cur' : ''}`}>\n        <div className=\"mh-ftop\">\n          <p className=\"mh-ftitle\">{title}</p>\n          <span className={`mh-fdone${step > k ? ' show' : ''}`}><Check size={12} aria-hidden=\"true\" /></span>\n        </div>\n        {children}\n      </div>\n    </>\n  )\n}\n\nfunction FlowMeter({ label, value, score, on }: { label: string; value: number; score: string; on: boolean }) {\n  return (\n    <div className=\"mh-meter\">\n      <div className=\"mh-meter-top\"><span>{label}</span><span className=\"mh-num\">{score}</span></div>\n      <div className=\"mh-meter-bar\"><i style={{ width: on ? `${value}%` : '0%', transition: 'width .9s ease' }} /></div>\n    </div>\n  )\n}\n\nexport default function HeroSection({ onAuth }: CtaProps) {\n  const reduce = useReducedMotion()\n  const [i, setI] = useState(0)\n  const [s, setS] = useState(0)\n\n  useEffect(() => {\n    if (reduce) return\n    const t = setInterval(() => setI((v) => (v + 1) % careers.length), 3800)\n    return () => clearInterval(t)\n  }, [reduce])\n\n  useEffect(() => {\n    if (reduce) return\n    const t = setTimeout(() => setS((v) => (v >= DONE ? 0 : v + 1)), s >= DONE ? 2800 : 1400)\n    return () => clearTimeout(t)\n  }, [s, reduce])\n\n  const c = careers[i]\n  const step = reduce ? DONE : s\n  const scores = ['4.6', '4.4', '4.7']\n  const vals = [92, 88, 94]\n  const ticker = [...careers, ...careers]\n\n  return (\n    <section className=\"mh-hero\">\n      <div className=\"mh-blob\" style={{ width: 380, height: 380, background: '#93C5FD', top: -80, right: '8%' }} />\n      <div className=\"mh-blob\" style={{ width: 320, height: 320, background: '#C4B5FD', top: 160, left: '-4%', animationDelay: '-5s' }} />\n      <div className=\"mh-blob\" style={{ width: 260, height: 260, background: '#A5F3FC', bottom: 60, right: '32%', animationDelay: '-9s' }} />\n\n      <div className=\"mh-wrap mh-hero-grid\">\n        <Reveal>\n          <span className=\"mh-pill\"><span className=\"mh-dot\" /> A professional network built on peer evidence</span>\n          <h1 className=\"mh-h1\">\n            Don&apos;t Just List Your Skills. <span className=\"mh-grad\">Prove Them.</span>\n          </h1>\n          <p className=\"mh-sub\">\n            Build your professional portfolio through real peer interviews, structured feedback, and evidence of what you can actually do.\n          </p>\n          <div className=\"mh-cta-row\">\n            <button className=\"mh-btn mh-btn-primary\" onClick={onAuth}>Build My Portfolio <ArrowRight size={18} aria-hidden=\"true\" /></button>\n            <a className=\"mh-btn mh-btn-ghost\" href=\"#how-it-works\">See How It Works</a>\n          </div>\n          <p className=\"mh-trust\">Real people · Real interviews · Real feedback · Real evidence</p>\n\n          <div className=\"mh-career\" aria-live=\"polite\">\n            <p className=\"mh-career-lbl\">Build your proof for</p>\n            <AnimatePresence mode=\"wait\">\n              <motion.div key={c.id} initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -12 }} transition={{ duration: 0.3 }}>\n                <p className=\"mh-career-name\">{c.name}</p>\n                <div className=\"mh-roles-row\">{c.roles.map((r) => <span className=\"mh-role\" key={r}>{r}</span>)}</div>\n                <div className=\"mh-skill-row\">\n                  {c.skills.map((x, n) => <span className=\"mh-sk mh-pop\" style={{ animationDelay: `${n * 0.1}s` }} key={x}>{x}</span>)}\n                </div>\n              </motion.div>\n            </AnimatePresence>\n            {!reduce && <span className=\"mh-cprog\"><i key={c.id} /></span>}\n            <div className=\"mh-dots\">\n              {careers.map((x, k) => (\n                <button key={x.id} className={k === i ? 'on' : ''} aria-label={`Show ${x.name}`} aria-pressed={k === i} onClick={() => setI(k)} />\n              ))}\n            </div>\n          </div>\n        </Reveal>\n\n        <Reveal delay={0.1}>\n          <div className=\"mh-flow\" aria-label=\"Illustration of how an MMI profile builds evidence\">\n            <div className=\"mh-flow-tag\"><PreviewBadge label=\"Illustrative example\" /></div>\n            <FlowCard k={0} step={step} title=\"Your MMI profile\">\n              <div className=\"mh-fprof\">\n                <span className=\"mh-photo\" aria-hidden=\"true\">You</span>\n                <div><p className=\"mh-num\">Your Name</p><p className=\"mh-small\">{c.roles[0]} · @username</p></div>\n              </div>\n              <div className=\"mh-skill-row\" key={c.id}>\n                {c.skills.map((x, n) => <span className=\"mh-sk mh-pop\" style={{ animationDelay: `${n * 0.1}s` }} key={x}>{x}</span>)}\n              </div>\n            </FlowCard>\n            <FlowCard k={1} step={step} title=\"Peer interview\">\n              <div className=\"mh-row\" style={{ fontWeight: 700, fontSize: 14 }}>\n                <span>You</span><ArrowLeftRight size={16} color=\"#2563EB\" aria-hidden=\"true\" /><span>Your peer</span>\n              </div>\n              <Waveform bars={28} />\n            </FlowCard>\n            <FlowCard k={2} step={step} title=\"Peer feedback\">\n              {c.skills.map((x, n) => <FlowMeter key={x} label={x} value={vals[n]} score={`${scores[n]} / 5`} on={step >= 2} />)}\n            </FlowCard>\n            <FlowCard k={3} step={step} title=\"Skill evidence\">\n              <div className=\"mh-frow\" style={{ marginTop: 0 }}>\n                <span>{c.skills[0]}</span>\n                {step >= 3 && <span className=\"mh-ok mh-pop\"><Check size={13} style={{ verticalAlign: -2 }} aria-hidden=\"true\" /> Peer validated · 12 evaluations</span>}\n              </div>\n            </FlowCard>\n            <FlowCard k={4} step={step} title=\"Professional portfolio\">\n              <div className=\"mh-frow\" style={{ marginTop: 0 }}>\n                <span>Share your proof</span><Link2 size={16} color=\"#2563EB\" aria-hidden=\"true\" />\n              </div>\n            </FlowCard>\n          </div>\n        </Reveal>\n      </div>\n\n      <div className=\"mh-marquee\" aria-hidden=\"true\">\n        <div className=\"mh-track\">\n          {ticker.map((x, k) => <span className=\"mh-tick\" key={k}>{x.name}</span>)}\n        </div>\n      </div>\n    </section>\n  )\n}\n","MarketingFooter.tsx":"import Link from 'next/link'\nimport { Logo } from './Brand'\n\nconst links = [\n  { href: '/about', label: 'About' },\n  { href: '/blog', label: 'Blog' },\n  { href: '/contact', label: 'Contact' },\n  { href: '/privacy', label: 'Privacy' },\n  { href: '/terms', label: 'Terms' },\n  { href: '/cookies', label: 'Cookies' },\n  { href: '/refund', label: 'Refunds' },\n]\n\nexport default function MarketingFooter() {\n  return (\n    <footer className=\"mh-footer\">\n      <div className=\"mh-wrap mh-foot-in\">\n        <div><Logo light /><p style={{ fontSize: 14, marginTop: 8 }}>&copy; MatchMyInterview. Built in India.</p></div>\n        <nav aria-label=\"Footer\" className=\"mh-foot-links\">\n          {links.map((l) => <Link key={l.href} href={l.href}>{l.label}</Link>)}\n        </nav>\n      </div>\n    </footer>\n  )\n}\n","MarketingNav.tsx":"'use client'\n\nimport { useEffect, useState } from 'react'\nimport Link from 'next/link'\nimport { Menu, X } from 'lucide-react'\nimport { motion, useScroll, useSpring } from 'framer-motion'\nimport { Logo } from './Brand'\nimport type { CtaProps } from './shared'\n\nconst links = [\n  { href: '#how-it-works', label: 'How it works' },\n  { href: '#skills', label: 'Evidence' },\n  { href: '/blog', label: 'Blog' },\n]\n\nexport default function MarketingNav({ onAuth }: CtaProps) {\n  const [scrolled, setScrolled] = useState(false)\n  const [open, setOpen] = useState(false)\n  const { scrollYProgress } = useScroll()\n  const scaleX = useSpring(scrollYProgress, { stiffness: 120, damping: 28 })\n\n  useEffect(() => {\n    const f = () => setScrolled(window.scrollY > 12)\n    window.addEventListener('scroll', f, { passive: true })\n    return () => window.removeEventListener('scroll', f)\n  }, [])\n\n  return (\n    <>\n      <motion.div className=\"mh-progress\" style={{ scaleX }} aria-hidden=\"true\" />\n      <header className={`mh-nav${scrolled ? ' scrolled' : ''}`}>\n        <nav aria-label=\"Main\" className=\"mh-wrap mh-nav-in\">\n          <Logo />\n          <div className=\"mh-links\">\n            {links.map((l) => (\n              <Link key={l.href} href={l.href}>{l.label}</Link>\n            ))}\n            <button className=\"mh-btn mh-btn-primary mh-btn-sm\" onClick={onAuth}>Build My Portfolio</button>\n          </div>\n          <button\n            className=\"mh-burger\"\n            aria-label={open ? 'Close menu' : 'Open menu'}\n            aria-expanded={open}\n            aria-controls=\"mh-mobile\"\n            onClick={() => setOpen((v) => !v)}\n          >\n            {open ? <X size={22} /> : <Menu size={22} />}\n          </button>\n        </nav>\n        {open && (\n          <div id=\"mh-mobile\" className=\"mh-mobile\">\n            {links.map((l) => (\n              <Link key={l.href} href={l.href} onClick={() => setOpen(false)}>{l.label}</Link>\n            ))}\n            <button className=\"mh-btn mh-btn-primary\" style={{ width: '100%', marginTop: 8 }} onClick={() => { setOpen(false); onAuth() }}>\n              Get started\n            </button>\n          </div>\n        )}\n      </header>\n    </>\n  )\n}\n","PortfolioPreviewSection.tsx":"'use client'\n\nimport { Check } from 'lucide-react'\nimport { CountUp, Meter, PreviewBadge, Reveal, SectionHeader } from './shared'\n\nconst parts = ['Name and photo', 'Username', 'Professional headline', 'Target role', 'About', 'Skills', 'Peer-validated skills', 'Interview history', 'Peer feedback', 'Achievements', 'MMI score and reputation', 'Education', 'Experience', 'Projects', 'LinkedIn and GitHub']\n\nexport default function PortfolioPreviewSection() {\n  return (\n    <section className=\"mh-sec\" style={{ background: 'var(--soft)' }}>\n      <div className=\"mh-wrap\">\n        <SectionHeader eyebrow=\"The outcome\" title=\"Every interview makes your profile stronger.\" description=\"Your profile grows into a professional portfolio you can share, backed by evidence from real peers.\" />\n        <div className=\"mh-pfx\">\n          <Reveal>\n            <div className=\"mh-pf-card\">\n              <PreviewBadge label=\"Illustrative profile\" />\n              <div className=\"mh-fprof\" style={{ marginTop: 16 }}>\n                <span className=\"mh-photo\" style={{ width: 56, height: 56 }} aria-hidden=\"true\">SP</span>\n                <div><p className=\"mh-num\" style={{ fontSize: 18 }}>Sample Profile</p><p className=\"mh-small\">Software Engineer · @sampleprofile</p></div>\n              </div>\n              <p className=\"mh-small\" style={{ marginTop: 12 }}>Building skills through real peer interviews.</p>\n              <div className=\"mh-stats\"><div><b><CountUp to={842} /></b><span>MMI score</span></div><div><b><CountUp to={18} /></b><span>Interviews</span></div></div>\n              <Meter label=\"React  4.6 ★\" value={92} />\n              <Meter label=\"Node.js  4.4 ★\" value={88} />\n              <Meter label=\"System Design  4.7 ★\" value={94} />\n              <p className=\"mh-ok\" style={{ marginTop: 12 }}><Check size={13} style={{ verticalAlign: -2 }} aria-hidden=\"true\" /> Peer validated</p>\n              <div className=\"mh-fb\">&ldquo;Strong analytical thinking and a clear way of explaining trade-offs.&rdquo;</div>\n            </div>\n          </Reveal>\n          <Reveal delay={0.1}>\n            <div className=\"mh-pf-card\">\n              <p className=\"mh-bold\">What your portfolio brings together</p>\n              <div className=\"mh-parts\">{parts.map((p) => <span key={p}>{p}</span>)}</div>\n              <p className=\"mh-small\" style={{ marginTop: 16 }}>All values shown here are sample data for illustration. Richer profiles and portfolios are coming soon.</p>\n            </div>\n          </Reveal>\n        </div>\n      </div>\n    </section>\n  )\n}\n","ProductLoopSection.tsx":"'use client'\n\nimport { useEffect, useState } from 'react'\nimport { AnimatePresence, motion } from 'framer-motion'\nimport { Award, FileText, Mic, Search, UserPlus, Share2 } from 'lucide-react'\nimport { Meter, PreviewBadge, SectionHeader, StatusBadge, Waveform } from './shared'\n\nconst steps = [\n  { icon: UserPlus, n: '01', title: 'Build your professional profile', body: 'Name, photo, headline, target role, skills, projects and links.', status: 'partial' },\n  { icon: Search, n: '02', title: 'Find a peer', body: 'Meet people preparing for similar roles or working on similar skills.', status: 'live' },\n  { icon: Mic, n: '03', title: 'Interview each other', body: 'Two people, two roles, one valuable session.', status: 'live' },\n  { icon: FileText, n: '04', title: 'Give and receive structured feedback', body: 'Rate each other on a clear rubric, with written feedback.', status: 'soon' },\n  { icon: Award, n: '05', title: 'Build skill evidence', body: 'Skills move from self-declared to peer-validated.', status: 'soon' },\n  { icon: Share2, n: '06', title: 'Build your professional portfolio', body: 'Your profile becomes proof you can share.', status: 'soon' },\n] as const\n\nfunction RoleSwap() {\n  const [flip, setFlip] = useState(false)\n  useEffect(() => {\n    const t = setInterval(() => setFlip((v) => !v), 2400)\n    return () => clearInterval(t)\n  }, [])\n  const a = flip ? 'Interviewer' : 'Candidate'\n  const b = flip ? 'Candidate' : 'Interviewer'\n  return (\n    <>\n      <div className=\"mh-swap\">\n        {[['You', a], ['Your peer', b]].map(([who, role]) => (\n          <div className=\"mh-swap-box\" key={who}>\n            <span>{who}</span>\n            <AnimatePresence mode=\"wait\">\n              <motion.b key={role} initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -8 }} transition={{ duration: 0.2 }}>{role}</motion.b>\n            </AnimatePresence>\n            {who === 'You' && null}\n          </div>\n        )).reduce<React.ReactNode[]>((acc, el, k) => (k === 0 ? [el] : [...acc, <span key=\"x\" style={{ fontWeight: 800, color: '#2563EB' }}>⇄</span>, el]), [])}\n      </div>\n      <p className=\"mh-small\" style={{ marginTop: 14 }}>Then you switch. You don&apos;t just get interviewed. You interview another peer too.</p>\n    </>\n  )\n}\n\nfunction Panel({ i }: { i: number }) {\n  if (i === 0)\n    return (\n      <div className=\"mh-mock\">\n        <p className=\"mh-bold\">Your professional profile</p>\n        <div className=\"mh-pgrid\">\n          {['Name and photo', 'Username', 'Headline', 'Target role', 'Skills', 'Experience', 'Education', 'Projects', 'LinkedIn / GitHub'].map((x) => <span key={x}>{x}</span>)}\n        </div>\n      </div>\n    )\n  if (i === 1)\n    return (\n      <div className=\"mh-mock\">\n        <p className=\"mh-bold\">Peers across careers <span className=\"mh-small\">(illustrative)</span></p>\n        {[['Software Engineer', 'React · Node.js · SQL'], ['Data Analyst', 'SQL · Python · Analytics'], ['Consultant', 'Strategy · Case Interviews'], ['Finance', 'Financial Modeling · Excel'], ['Government', 'Aptitude · Reasoning · General Studies']].map(([r, s]) => (\n          <div className=\"mh-peer\" key={r}><div className=\"grow\"><p className=\"mh-bold\" style={{ fontSize: 14 }}>{r}</p><p className=\"mh-small\">{s}</p></div><span className=\"mh-online\">Active</span></div>\n        ))}\n      </div>\n    )\n  if (i === 2)\n    return (\n      <div className=\"mh-mock\">\n        <p className=\"mh-bold\">Two people. Two roles. One valuable session.</p>\n        <Waveform bars={34} />\n        <RoleSwap />\n      </div>\n    )\n  if (i === 3)\n    return (\n      <div className=\"mh-mock\">\n        <p className=\"mh-bold\">Interview feedback</p>\n        <Meter label=\"Technical Knowledge  4.5 / 5\" value={90} />\n        <Meter label=\"Problem Solving  4.4 / 5\" value={88} />\n        <Meter label=\"Communication  4.7 / 5\" value={94} />\n        <Meter label=\"Role Knowledge  4.3 / 5\" value={86} />\n        <div className=\"mh-fb\">&ldquo;Strong reasoning and clear communication. Good approach to solving unfamiliar problems.&rdquo;</div>\n      </div>\n    )\n  if (i === 4)\n    return (\n      <div className=\"mh-mock\">\n        <p className=\"mh-bold\">Evidence for one skill</p>\n        <div className=\"mh-pgrid\">\n          {['Self-declared', 'Interviewed', 'Peer evaluated', 'Peer validated'].map((x, k) => <span key={x}>{k + 1}. {x}</span>)}\n        </div>\n        <p className=\"mh-small\" style={{ marginTop: 12 }}>You can declare your skills. You cannot declare your own validation score. Only completed peer interactions create evidence.</p>\n      </div>\n    )\n  return (\n    <div className=\"mh-mock\">\n      <p className=\"mh-bold\">Your portfolio</p>\n      <div className=\"mh-parts\">\n        {['Skills', 'Peer-validated skills', 'Interview history', 'Peer feedback', 'Achievements', 'MMI score', 'Projects', 'Education', 'Links'].map((x) => <span key={x}>{x}</span>)}\n      </div>\n      <p className=\"mh-small\" style={{ marginTop: 12 }}>Share your proof with a link.</p>\n    </div>\n  )\n}\n\nexport default function ProductLoopSection() {\n  const [active, setActive] = useState(0)\n  const [auto, setAuto] = useState(true)\n  useEffect(() => {\n    if (!auto) return\n    const t = setTimeout(() => setActive((v) => (v + 1) % steps.length), 5000)\n    return () => clearTimeout(t)\n  }, [active, auto])\n\n  return (\n    <section id=\"how-it-works\" className=\"mh-sec\" style={{ scrollMarginTop: 70, background: 'var(--soft)' }}>\n      <div className=\"mh-wrap\">\n        <SectionHeader eyebrow=\"How it works\" title=\"From profile to proof in six steps\" description=\"The interview is the mechanism. Your portfolio is the outcome.\" />\n        <div className=\"mh-loop\">\n          <div className=\"mh-steps\" role=\"tablist\" aria-label=\"How MatchMyInterview works\">\n            {steps.map((s, k) => (\n              <button key={s.n} role=\"tab\" aria-selected={active === k} className={`mh-step${active === k ? ' on' : ''}${auto ? ' auto' : ''}`} onClick={() => { setAuto(false); setActive(k) }}>\n                <span className=\"mh-step-num\">{s.n}</span>\n                <span>\n                  <span className=\"mh-step-title\">{s.title} <StatusBadge status={s.status} /></span>\n                  <span className=\"mh-step-body\" style={{ display: 'block' }}>{s.body}</span>\n                </span>\n                <span className=\"mh-step-bar\"><i key={`${active}-${auto}`} /></span>\n              </button>\n            ))}\n          </div>\n          <div className=\"mh-panel\" role=\"tabpanel\">\n            <div className=\"mh-panel-top\">\n              <span className=\"mh-bold\">{steps[active].n} · {steps[active].title}</span>\n              <PreviewBadge label=\"Illustrative\" />\n            </div>\n            <AnimatePresence mode=\"wait\">\n              <motion.div key={active} initial={{ opacity: 0, y: 14 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }} transition={{ duration: 0.28 }}>\n                <Panel i={active} />\n              </motion.div>\n            </AnimatePresence>\n          </div>\n        </div>\n      </div>\n    </section>\n  )\n}\n","ResumeVsEvidenceSection.tsx":"'use client'\n\nimport { CountUp, Meter, PreviewBadge, Reveal, SectionHeader } from './shared'\n\nconst claims = [['SQL', 'Advanced'], ['Python', 'Advanced'], ['Communication', 'Excellent'], ['Problem Solving', 'Strong']]\nconst proof = [\n  ['SQL', '4.6', 'Peer validated', '12 evaluations · 8 independent peers'],\n  ['Python', '4.4', 'Peer validated', '7 evaluations'],\n  ['Communication', '4.7', 'Peer evaluated', '10 evaluations'],\n]\n\nexport default function ResumeVsEvidenceSection() {\n  return (\n    <section className=\"mh-sec\">\n      <div className=\"mh-wrap\">\n        <SectionHeader\n          eyebrow=\"The difference\"\n          title={<>LinkedIn tells people what you can do.<br /><span className=\"mh-grad\">MMI shows the evidence.</span></>}\n        />\n        <div className=\"mh-cmp2\">\n          <Reveal>\n            <div className=\"mh-cmp2-a\" style={{ height: '100%' }}>\n              <h3 style={{ color: '#64748B' }}>Traditional profile <span className=\"mh-badge mh-b-planned\">Self-declared</span></h3>\n              {claims.map(([s, l]) => (\n                <div className=\"mh-sr\" key={s}><b>{s}</b><span style={{ color: '#94A3B8' }}>{l}</span></div>\n              ))}\n            </div>\n          </Reveal>\n          <Reveal delay={0.1}>\n            <div className=\"mh-cmp2-b\" style={{ height: '100%' }}>\n              <h3 style={{ color: '#2563EB' }}>MMI profile <PreviewBadge label=\"Example\" /></h3>\n              {proof.map(([s, v, st, m]) => (\n                <div className=\"mh-sr\" key={s}>\n                  <div style={{ flex: 1, minWidth: 0 }}><b>{s}</b><p className=\"m\">{m}</p><div style={{ maxWidth: 220, marginTop: 6 }}><Meter value={parseFloat(v) * 20} /></div></div>\n                  <div style={{ textAlign: 'right' }}><span className=\"mh-score\"><CountUp to={parseFloat(v)} decimals={1} /> / 5</span><p className=\"mh-ok\">{st}</p></div>\n                </div>\n              ))}\n            </div>\n          </Reveal>\n        </div>\n        <Reveal>\n          <p className=\"mh-quote\">Your resume and professional profile tell your story. MMI adds evidence from real peer interactions.</p>\n        </Reveal>\n      </div>\n    </section>\n  )\n}\n","SkillValidationSection.tsx":"'use client'\n\nimport { useEffect, useRef, useState } from 'react'\nimport { useInView, useReducedMotion } from 'framer-motion'\nimport { RotateCcw } from 'lucide-react'\nimport { CountUp, PreviewBadge, SectionHeader } from './shared'\n\nconst stages = [['Self-declared', 'You list the skill'], ['Interviewed', 'A peer asks about it'], ['Peer evaluated', 'Feedback is recorded'], ['Peer validated', 'Evidence accumulates']]\n\nexport default function SkillValidationSection() {\n  const ref = useRef<HTMLDivElement>(null)\n  const inView = useInView(ref, { once: true, margin: '-80px' })\n  const reduce = useReducedMotion()\n  const [s, setS] = useState(0)\n  const stage = reduce ? 3 : s\n\n  useEffect(() => {\n    if (!inView || reduce || s >= 3) return\n    const t = setTimeout(() => setS(s + 1), 1300)\n    return () => clearTimeout(t)\n  }, [inView, reduce, s])\n\n  return (\n    <section id=\"skills\" className=\"mh-sec mh-dark\" style={{ scrollMarginTop: 70 }}>\n      <div className=\"mh-wrap\">\n        <SectionHeader eyebrow=\"Skill evidence\" title=\"Anyone can declare a skill. Evidence is earned.\" description=\"Users can declare their skills, but they cannot declare their own validation score. Only completed peer interactions generate validation evidence.\" />\n        <div className=\"mh-demo\" ref={ref}>\n          <div className=\"mh-demo-top\">\n            <span style={{ fontWeight: 700 }}>Example: one skill, four stages</span>\n            <PreviewBadge label=\"Illustrative, not real data\" />\n          </div>\n          <div className=\"mh-ladder\">\n            {stages.map(([a, b], k) => (\n              <div key={a} className={`mh-stage${stage >= k ? ' on' : ''}`}>{a}<small>{b}</small></div>\n            ))}\n          </div>\n          <div className=\"mh-ladbar\"><i style={{ width: `${(stage / 3) * 100}%` }} /></div>\n          <div className=\"mh-big\" style={{ opacity: stage === 3 ? 1 : 0.35, transition: 'opacity .5s' }}>\n            <strong>{stage === 3 ? <CountUp to={4.6} decimals={1} /> : '0.0'} / 5</strong>\n            <span>SQL · 12 evaluations · 8 independent peers</span>\n          </div>\n          {!reduce && <button className=\"mh-btn mh-btn-glass mh-btn-sm\" style={{ marginTop: 18 }} onClick={() => setS(0)}><RotateCcw size={15} aria-hidden=\"true\" /> Replay</button>}\n          <p className=\"mh-demo-note\">Peer-evaluated evidence based on completed MMI interviews. It is not a formal professional certification. This feature is coming soon.</p>\n        </div>\n      </div>\n    </section>\n  )\n}\n","SocialProofSection.tsx":"'use client'\n\nimport { Check, Clock } from 'lucide-react'\nimport { Reveal, SectionHeader } from './shared'\n\nconst live = ['Peer matching by domain and role', 'Interview sessions with chat', 'Invites and session flow', 'Blog with interview guides']\nconst next = ['Richer professional profiles', 'Structured peer feedback', 'Peer-validated skill evidence', 'MMI score and reputation', 'Shareable portfolio']\n\nexport default function SocialProofSection() {\n  return (\n    <section className=\"mh-sec\" style={{ background: 'var(--soft)' }}>\n      <div className=\"mh-wrap\">\n        <SectionHeader eyebrow=\"Built in public\" title=\"What works today, and what is next\" description=\"We would rather show you our progress than invent numbers.\" />\n        <div className=\"mh-road\">\n          <Reveal>\n            <div className=\"mh-road-card\" style={{ height: '100%' }}>\n              <h3 className=\"mh-h3\">Live now</h3>\n              <ul style={{ marginTop: 10 }}>\n                {live.map((x) => <li key={x}><span className=\"mh-tick-ico\" style={{ background: '#D1FAE5', color: '#047857' }}><Check size={15} aria-hidden=\"true\" /></span>{x}</li>)}\n              </ul>\n            </div>\n          </Reveal>\n          <Reveal delay={0.1}>\n            <div className=\"mh-road-card\" style={{ height: '100%' }}>\n              <h3 className=\"mh-h3\">Coming next</h3>\n              <ul style={{ marginTop: 10 }}>\n                {next.map((x) => <li key={x} style={{ color: '#475569' }}><span className=\"mh-tick-ico\"><Clock size={14} aria-hidden=\"true\" /></span>{x}</li>)}\n              </ul>\n            </div>\n          </Reveal>\n        </div>\n      </div>\n    </section>\n  )\n}\n","TalentPreviewSection.tsx":"'use client'\n\nimport { Lock } from 'lucide-react'\nimport { Reveal, StatusBadge } from './shared'\n\nexport default function TalentPreviewSection() {\n  return (\n    <section className=\"mh-sec\" style={{ paddingTop: 0 }}>\n      <div className=\"mh-wrap\">\n        <Reveal>\n          <div className=\"mh-talent\">\n            <StatusBadge status=\"planned\" />\n            <h2 className=\"mh-h2\" style={{ marginTop: 16, fontSize: 'clamp(1.6rem,3vw,2.3rem)' }}>Coming later</h2>\n            <p className=\"mh-lead\" style={{ maxWidth: 560, margin: '14px auto 0' }}>\n              Recruiter search, company accounts and talent discovery are planned for a later stage, with you in control of what is shared. They are not available today.\n            </p>\n            <div aria-hidden=\"true\" style={{ marginTop: 26 }}>\n              {[70, 55, 62].map((w, k) => (\n                <div className=\"mh-skel\" key={k}><i style={{ width: 36, height: 36, borderRadius: '50%' }} /><i style={{ width: `${w}%` }} /></div>\n              ))}\n            </div>\n            <p className=\"mh-small\" style={{ marginTop: 18, display: 'inline-flex', alignItems: 'center', gap: 6 }}><Lock size={14} aria-hidden=\"true\" /> Opt-in only</p>\n          </div>\n        </Reveal>\n      </div>\n    </section>\n  )\n}\n","TwoSidedValueSection.tsx":"'use client'\n\nimport { Check } from 'lucide-react'\nimport { GlowCard, Reveal, SectionHeader, StaggerItem } from './shared'\n\nconst sides = [\n  { t: 'As a candidate', p: ['Practice answering', 'Demonstrate your skills', 'Receive peer feedback', 'Build evidence', 'Improve your portfolio'] },\n  { t: 'As an interviewer', p: ['Practice interviewing', 'Help another professional', 'Build interviewer reputation', 'Earn XP and achievements', 'Strengthen your own professional profile'] },\n]\n\nexport default function TwoSidedValueSection() {\n  return (\n    <section className=\"mh-sec\">\n      <div className=\"mh-wrap\">\n        <SectionHeader eyebrow=\"Both sides\" title=\"Build your portfolio from both sides of the interview.\" />\n        <div className=\"mh-two\">\n          {sides.map((s, k) => (\n            <Reveal key={s.t} delay={k * 0.1}>\n              <GlowCard>\n                <h3 className=\"mh-h3\">{s.t}</h3>\n                <ul className=\"mh-list\" style={{ marginTop: 8 }}>\n                  {s.p.map((x, n) => (\n                    <StaggerItem key={x} i={n}>\n                      <span className=\"mh-tick-ico\"><Check size={15} aria-hidden=\"true\" /></span>{x}\n                    </StaggerItem>\n                  ))}\n                </ul>\n              </GlowCard>\n            </Reveal>\n          ))}\n        </div>\n        <Reveal><p className=\"mh-banner\">Every session helps both people build their professional reputation.</p></Reveal>\n      </div>\n    </section>\n  )\n}\n","careers.ts":"export type Career = { id: string; name: string; roles: string[]; skills: string[] }\n\nexport const careers: Career[] = [\n  { id: 'software', name: 'Software Engineering', roles: ['Software Engineer', 'Frontend Developer', 'Backend Developer', 'Full Stack Developer'], skills: ['React', 'Node.js', 'System Design'] },\n  { id: 'data', name: 'Data & Analytics', roles: ['Data Analyst', 'Data Scientist', 'Business Analyst'], skills: ['SQL', 'Python', 'Analytics'] },\n  { id: 'consulting', name: 'Consulting', roles: ['Strategy Consultant', 'Management Consultant', 'Business Consultant'], skills: ['Case Interviews', 'Strategy', 'Problem Solving'] },\n  { id: 'finance', name: 'Finance', roles: ['Financial Analyst', 'Investment Banking', 'Risk Analyst'], skills: ['Excel', 'Financial Modeling', 'Valuation'] },\n  { id: 'product', name: 'Product', roles: ['Product Manager', 'Product Analyst'], skills: ['Product Sense', 'Metrics', 'Prioritization'] },\n  { id: 'government', name: 'Government', roles: ['Civil Services', 'PSU', 'Public Sector roles'], skills: ['Reasoning', 'Aptitude', 'General Studies'] },\n  { id: 'marketing', name: 'Marketing', roles: ['Digital Marketing', 'Growth', 'Brand Marketing'], skills: ['SEO', 'Analytics', 'Brand Strategy'] },\n]\n","marketing-v2.css":"/* v2 refinements: calmer, product-focused. Loaded after marketing.css. */\n.mh{--soft:#F7F8FA}\n.mh-hero-grid{align-items:start;padding-bottom:72px}\n.mh-glow,.mh-pf-card,.mh-mock,.mh-panel,.mh-road-card,.mh-fcard,.mh-career{border-radius:16px}\n.mh-cta,.mh-talent{border-radius:22px}\n.mh-logo-img{width:32px;height:32px;border-radius:8px;object-fit:contain}\n.mh-trust{margin-top:22px;font-size:14px;font-weight:600;color:#334155}\n\n/* career selector */\n.mh-career{margin-top:28px;padding:18px;border:1px solid var(--line);background:#fff;box-shadow:0 14px 30px -24px rgba(15,23,42,.35)}\n.mh-career-lbl{font-size:12px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}\n.mh-career-name{font-size:clamp(1.3rem,2.6vw,1.7rem);font-weight:800;letter-spacing:-.02em;margin-top:4px;min-height:40px}\n.mh-roles-row,.mh-skill-row{display:flex;flex-wrap:wrap;gap:8px;margin-top:10px}\n.mh-role{font-size:13px;font-weight:600;padding:4px 10px;border-radius:8px;background:#F1F5F9;color:#334155}\n.mh-sk{font-size:13px;font-weight:600;padding:4px 10px;border-radius:8px;background:#EFF6FF;color:#1D4ED8;border:1px solid #DBEAFE}\n.mh-dots{display:flex;gap:8px;margin-top:14px}\n.mh-dots button{width:26px;height:6px;border-radius:99px;background:#CBD5E1;transition:all .3s}\n.mh-dots button.on{width:44px;background:#2563EB}\n.mh-dots button:focus-visible{outline:2px solid #93C5FD;outline-offset:3px}\n\n/* hero flow */\n.mh-ftitle{font-size:11px;font-weight:800;letter-spacing:.09em;text-transform:uppercase;color:var(--muted);margin-bottom:8px}\n.mh-fprof{display:flex;gap:12px;align-items:center}\n.mh-photo{flex:none;width:44px;height:44px;border-radius:50%;background:#E2E8F0;display:grid;place-items:center;color:#64748B;font-weight:800;font-size:14px}\n.mh-num{font-weight:800;font-variant-numeric:tabular-nums}\n.mh-frow{display:flex;justify-content:space-between;font-size:13px;margin-top:6px;font-weight:600}\n\n/* compare */\n.mh-cmp2{display:grid;grid-template-columns:1fr 1.15fr;gap:20px;margin-top:48px;align-items:stretch}\n@media(max-width:820px){.mh-cmp2{grid-template-columns:1fr}}\n.mh-cmp2-a{border:1px dashed #CBD5E1;border-radius:16px;padding:26px;background:#F8FAFC}\n.mh-cmp2-b{border:1px solid #93B4F8;border-radius:16px;padding:26px;background:#fff;box-shadow:0 24px 50px -32px rgba(37,99,235,.6)}\n.mh-cmp2 h3{font-size:13px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;display:flex;justify-content:space-between;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:6px}\n.mh-sr{display:flex;justify-content:space-between;gap:12px;padding:12px 0;border-bottom:1px solid var(--line);align-items:center}\n.mh-sr:last-of-type{border:0}\n.mh-sr b{font-weight:700}\n.mh-sr .m{font-size:12px;color:var(--muted)}\n.mh-score{font-size:20px;font-weight:800;color:#1D4ED8;font-variant-numeric:tabular-nums}\n.mh-ok{color:#047857;font-size:12px;font-weight:700}\n.mh-quote{text-align:center;max-width:620px;margin:34px auto 0;font-size:18px;color:#334155;font-weight:500}\n\n/* steps panel extras */\n.mh-pgrid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:12px}\n.mh-pgrid span{border:1px solid var(--line);border-radius:10px;padding:9px 12px;font-size:13px;font-weight:600;background:#fff}\n@media(max-width:520px){.mh-pgrid{grid-template-columns:1fr}}\n.mh-swap{display:grid;grid-template-columns:1fr auto 1fr;gap:10px;align-items:center;margin-top:14px}\n.mh-swap-box{border:1px solid var(--line);border-radius:12px;padding:14px;text-align:center;background:#fff}\n.mh-swap-box b{display:block;font-size:15px}\n.mh-swap-box span{font-size:12px;color:var(--muted)}\n\n/* ladder */\n.mh-ladder{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:22px}\n@media(max-width:640px){.mh-ladder{grid-template-columns:1fr 1fr}}\n.mh-stage{border:1px solid rgba(255,255,255,.16);border-radius:12px;padding:14px 12px;text-align:center;font-size:13px;font-weight:700;color:#8EA0BF;transition:all .5s}\n.mh-stage.on{background:#2563EB;border-color:#60A5FA;color:#fff;box-shadow:0 14px 30px -14px rgba(37,99,235,.9)}\n.mh-stage small{display:block;font-weight:500;opacity:.8;margin-top:2px}\n.mh-big{display:flex;align-items:baseline;gap:14px;flex-wrap:wrap;margin-top:24px}\n.mh-big strong{font-size:44px;font-weight:800;letter-spacing:-.03em}\n\n/* portfolio */\n.mh-pfx{max-width:980px;margin:48px auto 0;display:grid;grid-template-columns:.9fr 1.1fr;gap:22px;align-items:start}\n@media(max-width:820px){.mh-pfx{grid-template-columns:1fr}}\n.mh-stats{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:16px 0}\n.mh-stats div{border:1px solid var(--line);border-radius:12px;padding:12px;text-align:center}\n.mh-stats b{display:block;font-size:26px;font-weight:800;letter-spacing:-.02em}\n.mh-stats span{font-size:11px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}\n.mh-fb{margin-top:16px;padding:14px;border-radius:12px;background:#F8FAFC;font-size:14px;color:#334155;font-style:italic}\n.mh-parts{display:flex;flex-wrap:wrap;gap:8px;margin-top:14px}\n.mh-parts span{font-size:13px;font-weight:600;padding:7px 12px;border:1px solid var(--line);border-radius:10px;background:#fff}\n.mh-two{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-top:48px}\n@media(max-width:760px){.mh-two{grid-template-columns:1fr}}\n.mh-banner{margin:28px auto 0;max-width:640px;text-align:center;font-weight:600;font-size:17px;color:#1E3A8A;background:#EFF6FF;border:1px solid #DBEAFE;border-radius:12px;padding:16px 20px}\n\n/* animated hero flow */\n.mh-hero-grid{padding-bottom:56px}\n.mh-flow{position:relative;padding-top:6px}\n.mh-flow-tag{margin-bottom:10px}\n.mh-fcard{background:#fff;border:1px solid var(--line);padding:14px 16px;opacity:.4;transform:translateY(8px) scale(.985);filter:saturate(.4);transition:opacity .5s,transform .5s,filter .5s,border-color .4s,box-shadow .4s}\n.mh-fcard.on{opacity:1;transform:none;filter:none}\n.mh-fcard.cur{border-color:#7DA2F6;transform:scale(1.015);box-shadow:0 0 0 4px rgba(37,99,235,.12),0 22px 40px -22px rgba(37,99,235,.7)}\n.mh-ftop{display:flex;justify-content:space-between;align-items:center}\n.mh-fdone{width:18px;height:18px;border-radius:50%;background:#10B981;color:#fff;display:grid;place-items:center;transform:scale(0);transition:transform .35s cubic-bezier(.34,1.56,.64,1)}\n.mh-fdone.show{transform:scale(1)}\n.mh-fconn{position:relative;width:2px;height:16px;margin:0 auto;background:#D5DDEA}\n.mh-fconn i{position:absolute;left:0;top:0;width:100%;background:#2563EB;transition:height .5s}\n.mh-fconn b{position:absolute;left:-3px;top:-2px;width:8px;height:8px;border-radius:50%;background:#2563EB;box-shadow:0 0 10px #2563EB;animation:mh-travel .7s ease-in forwards}\n@keyframes mh-travel{from{top:-2px;opacity:1}to{top:12px;opacity:0}}\n.mh-pop{animation:mh-popin .5s cubic-bezier(.34,1.56,.64,1) both}\n@keyframes mh-popin{from{opacity:0;transform:scale(.8) translateY(6px)}to{opacity:1;transform:none}}\n.mh-fup{animation:mh-fadeup .5s ease both}\n@keyframes mh-fadeup{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}\n.mh-cprog{display:block;height:3px;border-radius:99px;background:#E5EAF2;margin-top:14px;overflow:hidden}\n.mh-cprog i{display:block;height:100%;width:0;background:linear-gradient(90deg,#2563EB,#7C3AED);animation:mh-fill 3.8s linear forwards}\n.mh-ladbar{height:4px;border-radius:99px;background:rgba(255,255,255,.14);margin-top:14px;overflow:hidden}\n.mh-ladbar i{display:block;height:100%;background:linear-gradient(90deg,#60A5FA,#A78BFA);transition:width 1.2s ease}\n.mh-hero .mh-marquee{margin-top:0}\n","marketing.css":"/* MMI homepage styles. Self-contained: does not rely on Tailwind. All classes are prefixed mh- and scoped under .mh */\n.mh{--ink:#0B1220;--muted:#5B6B82;--line:#E5EAF2;--primary:#2563EB;--violet:#7C3AED;--cyan:#06B6D4;--navy:#0B1929;--soft:#F5F8FF;\n  font-family:var(--font-inter),system-ui,-apple-system,\"Segoe UI\",sans-serif;color:var(--ink);background:#fff;line-height:1.6;overflow-x:clip;-webkit-font-smoothing:antialiased}\n:where(.mh) *,:where(.mh) *::before,:where(.mh) *::after{box-sizing:border-box}\n:where(.mh) h1,:where(.mh) h2,:where(.mh) h3,:where(.mh) p,:where(.mh) ul,:where(.mh) ol{margin:0;padding:0}\n:where(.mh) ul,:where(.mh) ol{list-style:none}\n:where(.mh) a{color:inherit;text-decoration:none}\n:where(.mh) button{font:inherit;cursor:pointer;border:0;background:none;color:inherit;padding:0}\n\n.mh-wrap{max-width:1160px;margin:0 auto;padding:0 20px}\n.mh-sec{padding:100px 0;position:relative}\n@media(max-width:700px){.mh-sec{padding:64px 0}}\n\n/* progress + nav */\n.mh-progress{position:fixed;top:0;left:0;right:0;height:3px;background:linear-gradient(90deg,#2563EB,#7C3AED,#06B6D4);transform-origin:0 50%;z-index:70}\n.mh-nav{position:sticky;top:0;z-index:60;transition:background .3s,border-color .3s,box-shadow .3s;border-bottom:1px solid transparent}\n.mh-nav.scrolled{background:rgba(255,255,255,.82);backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);border-color:var(--line);box-shadow:0 6px 24px -18px rgba(15,23,42,.4)}\n.mh-nav-in{display:flex;align-items:center;justify-content:space-between;height:68px}\n.mh-logo{display:flex;align-items:center;gap:10px;font-weight:800;font-size:18px;letter-spacing:-.02em}\n.mh-logo-mark{width:32px;height:32px;border-radius:10px;background:linear-gradient(135deg,#2563EB,#7C3AED);display:grid;place-items:center;color:#fff;font-size:14px;font-weight:800}\n.mh-links{display:flex;align-items:center;gap:28px}\n.mh-links a{font-size:14px;font-weight:500;color:var(--muted);transition:color .2s}\n.mh-links a:hover{color:var(--ink)}\n.mh-burger{display:none;width:44px;height:44px;border-radius:12px;align-items:center;justify-content:center}\n.mh-mobile{border-top:1px solid var(--line);background:#fff;padding:8px 20px 20px}\n.mh-mobile a{display:flex;align-items:center;min-height:48px;font-weight:600}\n@media(max-width:820px){.mh-links{display:none}.mh-burger{display:flex}}\n\n/* buttons */\n.mh-btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:48px;padding:0 26px;border-radius:14px;font-weight:600;font-size:16px;transition:transform .25s,box-shadow .25s,background .25s;position:relative;overflow:hidden}\n.mh-btn:focus-visible{outline:3px solid #93C5FD;outline-offset:3px}\n.mh-btn-primary{background:linear-gradient(135deg,#2563EB,#4F46E5);color:#fff;box-shadow:0 12px 30px -12px rgba(37,99,235,.8)}\n.mh-btn-primary:hover{transform:translateY(-2px);box-shadow:0 18px 36px -12px rgba(37,99,235,.9)}\n.mh-btn-primary::after{content:\"\";position:absolute;top:0;left:-120%;width:60%;height:100%;background:linear-gradient(100deg,transparent,rgba(255,255,255,.35),transparent);transform:skewX(-20deg);animation:mh-sheen 4s ease-in-out infinite}\n.mh-btn-ghost{background:#fff;border:1px solid var(--line);color:var(--ink)}\n.mh-btn-ghost:hover{border-color:#BFD0F5;transform:translateY(-2px);box-shadow:0 10px 24px -16px rgba(37,99,235,.5)}\n.mh-btn-white{background:#fff;color:#1E3A8A}\n.mh-btn-white:hover{transform:translateY(-2px);box-shadow:0 18px 40px -14px rgba(0,0,0,.5)}\n.mh-btn-sm{min-height:40px;padding:0 18px;font-size:14px;border-radius:12px}\n\n/* badges */\n.mh-badge{display:inline-flex;align-items:center;gap:6px;border-radius:999px;padding:2px 10px;font-size:12px;font-weight:700;border:1px solid transparent;white-space:nowrap}\n.mh-b-live{background:#ECFDF5;color:#047857;border-color:#A7F3D0}\n.mh-b-soon{background:#EFF6FF;color:#1D4ED8;border-color:#BFDBFE}\n.mh-b-planned{background:#F1F5F9;color:#475569;border-color:#E2E8F0}\n.mh-b-preview{background:#FFFBEB;color:#92400E;border-color:#FDE68A}\n\n/* hero */\n.mh-hero{position:relative;overflow:hidden;padding:56px 0 0;background:radial-gradient(1100px 520px at 85% -10%,#DCE8FF 0,transparent 60%),radial-gradient(800px 480px at -10% 15%,#EFE6FF 0,transparent 58%),#fff}\n.mh-blob{position:absolute;border-radius:50%;filter:blur(80px);opacity:.45;pointer-events:none;animation:mh-drift 16s ease-in-out infinite}\n.mh-hero-grid{display:grid;grid-template-columns:1.05fr .95fr;gap:48px;align-items:center;position:relative;z-index:1;padding-bottom:64px}\n@media(max-width:960px){.mh-hero-grid{grid-template-columns:1fr;gap:40px}}\n.mh-pill{display:inline-flex;align-items:center;gap:10px;background:#fff;border:1px solid var(--line);border-radius:999px;padding:6px 14px 6px 10px;font-size:13px;font-weight:600;color:#1D4ED8;box-shadow:0 8px 24px -16px rgba(37,99,235,.6)}\n.mh-dot{width:8px;height:8px;border-radius:50%;background:#10B981;box-shadow:0 0 0 0 rgba(16,185,129,.6);animation:mh-pulse 2s infinite}\n.mh-h1{font-size:clamp(2.5rem,5.6vw,4.4rem);line-height:1.04;letter-spacing:-.04em;font-weight:800;margin-top:22px}\n.mh-grad{background:linear-gradient(90deg,#2563EB,#7C3AED,#06B6D4,#2563EB);background-size:220% auto;-webkit-background-clip:text;background-clip:text;color:transparent;animation:mh-shine 7s linear infinite}\n.mh-sub{font-size:clamp(1rem,1.6vw,1.2rem);color:var(--muted);max-width:560px;margin-top:22px}\n.mh-rotator{display:flex;align-items:center;gap:8px;height:34px;margin-top:20px;font-weight:600;font-size:16px;color:var(--ink);overflow:hidden}\n.mh-rotator span.mh-rot-word{display:inline-block;color:#2563EB}\n.mh-cta-row{display:flex;gap:12px;flex-wrap:wrap;margin-top:30px}\n.mh-points{display:flex;flex-wrap:wrap;gap:10px 24px;margin-top:30px;font-size:14px;color:var(--muted)}\n.mh-points li{display:flex;align-items:center;gap:8px}\n.mh-points svg{color:#2563EB}\n\n.mh-stage{position:relative;height:470px}\n@media(max-width:560px){.mh-stage{height:430px}}\n.mh-fl{position:absolute;background:#fff;border:1px solid var(--line);border-radius:20px;padding:16px;box-shadow:0 30px 60px -30px rgba(30,58,138,.45)}\n.mh-fl-1{left:0;top:34px;width:80%;animation:mh-bob 7s ease-in-out infinite}\n.mh-fl-2{right:0;bottom:6px;width:68%;animation:mh-bob 8s ease-in-out -2s infinite}\n.mh-fl-3{right:4%;top:0;padding:10px 14px;border-radius:999px;display:flex;align-items:center;gap:8px;font-weight:700;font-size:13px;animation:mh-bob 6s ease-in-out -1s infinite}\n.mh-fl-tag{position:absolute;left:0;bottom:-6px}\n.mh-row{display:flex;align-items:center;justify-content:space-between;gap:8px}\n.mh-avatar{width:38px;height:38px;border-radius:50%;display:grid;place-items:center;color:#fff;font-weight:700;font-size:14px}\n.mh-av-a{background:linear-gradient(135deg,#2563EB,#06B6D4)}\n.mh-av-b{background:linear-gradient(135deg,#7C3AED,#EC4899)}\n.mh-wave{display:flex;align-items:center;gap:3px;height:40px;margin:14px 0 8px}\n.mh-wave i{display:block;flex:1;max-width:5px;height:100%;border-radius:3px;background:linear-gradient(#2563EB,#7C3AED);transform-origin:center;animation:mh-bar 1.2s ease-in-out infinite}\n.mh-meter{margin-top:10px}\n.mh-meter-top{display:flex;justify-content:space-between;font-size:12px;font-weight:600;color:var(--muted);margin-bottom:5px}\n.mh-meter-bar{height:8px;border-radius:99px;background:#EEF2F9;overflow:hidden}\n.mh-meter-bar i{display:block;height:100%;border-radius:99px;background:linear-gradient(90deg,#2563EB,#7C3AED)}\n.mh-small{font-size:12px;color:var(--muted)}\n.mh-bold{font-weight:700}\n\n.mh-marquee{position:relative;z-index:1;overflow:hidden;border-top:1px solid var(--line);background:rgba(255,255,255,.7);padding:18px 0;-webkit-mask-image:linear-gradient(90deg,transparent,#000 8%,#000 92%,transparent);mask-image:linear-gradient(90deg,transparent,#000 8%,#000 92%,transparent)}\n.mh-track{display:flex;gap:14px;width:max-content;animation:mh-scroll 34s linear infinite}\n.mh-marquee:hover .mh-track{animation-play-state:paused}\n.mh-tick{display:inline-flex;align-items:center;gap:8px;border:1px solid var(--line);background:#fff;border-radius:999px;padding:8px 16px;font-size:14px;font-weight:600;color:#334155;white-space:nowrap}\n.mh-tick svg{color:#2563EB}\n\n/* headings */\n.mh-head{max-width:680px;margin:0 auto;text-align:center}\n.mh-eyebrow{display:inline-block;font-size:13px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:#2563EB;background:#EFF6FF;border-radius:999px;padding:5px 14px;margin-bottom:16px}\n.mh-h2{font-size:clamp(1.9rem,3.8vw,3rem);line-height:1.1;letter-spacing:-.03em;font-weight:800}\n.mh-lead{margin-top:16px;color:var(--muted);font-size:clamp(1rem,1.5vw,1.15rem)}\n.mh-dark .mh-lead{color:#A9B8D0}\n.mh-dark .mh-eyebrow{background:rgba(96,165,250,.15);color:#93C5FD}\n\n/* loop */\n.mh-loop{display:grid;grid-template-columns:.85fr 1.15fr;gap:32px;margin-top:56px;align-items:stretch}\n@media(max-width:900px){.mh-loop{grid-template-columns:1fr}}\n.mh-steps{display:flex;flex-direction:column;gap:10px}\n.mh-step{position:relative;text-align:left;display:flex;gap:14px;padding:16px 18px;border-radius:18px;border:1px solid var(--line);background:#fff;transition:all .3s;overflow:hidden;width:100%}\n.mh-step:hover{border-color:#BFD0F5;transform:translateX(3px)}\n.mh-step:focus-visible{outline:3px solid #93C5FD;outline-offset:2px}\n.mh-step.on{border-color:#93B4F8;background:linear-gradient(180deg,#F7FAFF,#EEF4FF);box-shadow:0 18px 40px -26px rgba(37,99,235,.7)}\n.mh-step-num{flex:none;width:36px;height:36px;border-radius:11px;display:grid;place-items:center;background:#F1F5F9;color:#64748B;font-weight:800;font-size:14px;transition:.3s}\n.mh-step.on .mh-step-num{background:linear-gradient(135deg,#2563EB,#7C3AED);color:#fff}\n.mh-step-title{display:flex;align-items:center;gap:8px;flex-wrap:wrap;font-weight:700}\n.mh-step-body{font-size:14px;color:var(--muted);margin-top:2px}\n.mh-step-bar{position:absolute;left:0;bottom:0;height:3px;width:100%;background:transparent}\n.mh-step-bar i{display:block;height:100%;width:0;background:linear-gradient(90deg,#2563EB,#7C3AED)}\n.mh-step.on.auto .mh-step-bar i{animation:mh-fill 5s linear forwards}\n.mh-step.on:not(.auto) .mh-step-bar i{width:100%}\n.mh-panel{border:1px solid var(--line);border-radius:26px;padding:22px;min-height:420px;background:radial-gradient(500px 280px at 90% 0,#E6EEFF,transparent 70%),linear-gradient(180deg,#FAFCFF,#F2F6FF);position:relative;overflow:hidden}\n.mh-panel-top{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:18px;flex-wrap:wrap}\n.mh-mock{background:#fff;border:1px solid var(--line);border-radius:18px;padding:18px;box-shadow:0 20px 40px -28px rgba(30,58,138,.4)}\n.mh-field{display:flex;justify-content:space-between;align-items:center;padding:12px 14px;border:1px solid var(--line);border-radius:12px;margin-top:10px;font-size:14px}\n.mh-field span:first-child{color:var(--muted);font-weight:600}\n.mh-peer{display:flex;align-items:center;gap:12px;padding:12px;border:1px solid var(--line);border-radius:14px;margin-top:10px;background:#fff}\n.mh-peer .grow{flex:1;min-width:0}\n.mh-online{display:inline-flex;align-items:center;gap:6px;font-size:12px;color:#047857;font-weight:600}\n.mh-online::before{content:\"\";width:7px;height:7px;border-radius:50%;background:#10B981}\n.mh-bubble{max-width:82%;padding:10px 14px;border-radius:16px;font-size:14px;margin-top:10px}\n.mh-bubble.l{background:#F1F5F9;border-bottom-left-radius:4px}\n.mh-bubble.r{background:linear-gradient(135deg,#2563EB,#4F46E5);color:#fff;margin-left:auto;border-bottom-right-radius:4px}\n\n/* bento */\n.mh-bento{display:grid;grid-template-columns:repeat(6,1fr);gap:16px;margin-top:56px}\n.mh-bento>*:nth-child(1){grid-column:span 4}.mh-bento>*:nth-child(2){grid-column:span 2}\n.mh-bento>*:nth-child(3){grid-column:span 2}.mh-bento>*:nth-child(4){grid-column:span 4}\n@media(max-width:820px){.mh-bento>*{grid-column:span 6!important}}\n.mh-glow{position:relative;border:1px solid var(--line);border-radius:24px;background:#fff;padding:26px;overflow:hidden;transition:transform .3s,box-shadow .3s,border-color .3s}\n.mh-glow::before{content:\"\";position:absolute;inset:0;pointer-events:none;background:radial-gradient(420px circle at var(--mx,50%) var(--my,50%),rgba(37,99,235,.14),transparent 45%);opacity:0;transition:opacity .3s}\n.mh-glow:hover{transform:translateY(-5px);border-color:#BFD0F5;box-shadow:0 30px 50px -30px rgba(37,99,235,.5)}\n.mh-glow:hover::before{opacity:1}\n.mh-glow>*{position:relative}\n.mh-ico{width:48px;height:48px;border-radius:15px;display:grid;place-items:center;color:#fff;margin-bottom:16px}\n.mh-i1{background:linear-gradient(135deg,#2563EB,#06B6D4)}.mh-i2{background:linear-gradient(135deg,#7C3AED,#EC4899)}\n.mh-i3{background:linear-gradient(135deg,#0EA5E9,#2563EB)}.mh-i4{background:linear-gradient(135deg,#F59E0B,#EF4444)}\n.mh-h3{font-size:20px;font-weight:700;letter-spacing:-.01em;display:flex;align-items:center;gap:10px;flex-wrap:wrap}\n.mh-card-p{color:var(--muted);margin-top:8px;font-size:15px}\n\n/* roles */\n.mh-seg{display:inline-flex;background:#F1F5F9;border-radius:16px;padding:5px;margin-top:28px;position:relative}\n.mh-seg button{position:relative;z-index:1;padding:11px 24px;border-radius:12px;font-weight:700;font-size:15px;color:#64748B;transition:color .25s;min-height:44px}\n.mh-seg button.on{color:#fff}\n.mh-seg-pill{position:absolute;inset:0;border-radius:12px;background:linear-gradient(135deg,#2563EB,#7C3AED);box-shadow:0 10px 24px -12px rgba(37,99,235,.9)}\n.mh-roles{display:grid;grid-template-columns:1fr 1fr;gap:28px;margin-top:40px;align-items:center}\n@media(max-width:860px){.mh-roles{grid-template-columns:1fr}}\n.mh-list li{display:flex;gap:14px;padding:14px 0;border-bottom:1px solid var(--line);font-size:17px;font-weight:500}\n.mh-list li:last-child{border:0}\n.mh-tick-ico{flex:none;width:26px;height:26px;border-radius:50%;display:grid;place-items:center;background:#DBEAFE;color:#1D4ED8;margin-top:1px}\n\n/* dark demo */\n.mh-dark{background:radial-gradient(900px 420px at 15% 0,rgba(37,99,235,.35),transparent 60%),radial-gradient(700px 400px at 100% 100%,rgba(124,58,237,.3),transparent 60%),var(--navy);color:#fff;overflow:hidden}\n.mh-demo{max-width:820px;margin:52px auto 0;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.14);border-radius:28px;padding:28px;backdrop-filter:blur(10px)}\n.mh-demo-top{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap}\n.mh-lbl{font-size:12px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:#93A4C0;margin:24px 0 10px}\n.mh-chips{display:flex;flex-wrap:wrap;gap:10px;min-height:44px}\n.mh-chip{display:inline-flex;align-items:center;gap:8px;padding:9px 16px;border-radius:999px;font-weight:600;font-size:14px;transition:all .4s}\n.mh-chip.self{border:1px dashed #8EA0BF;color:#C4D0E4}\n.mh-chip.valid{background:linear-gradient(135deg,#2563EB,#7C3AED);color:#fff;box-shadow:0 10px 26px -10px rgba(99,102,241,.9)}\n.mh-sim{margin-top:24px;border-radius:18px;padding:18px;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.12)}\n.mh-sim .mh-meter-bar{background:rgba(255,255,255,.12)}\n.mh-sim .mh-meter-top{color:#B6C3DA}\n.mh-demo-note{margin-top:20px;font-size:13px;color:#93A4C0}\n.mh-btn-glass{background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.2);color:#fff}\n.mh-btn-glass:hover{background:rgba(255,255,255,.18)}\n.mh-btn-light{background:#fff;color:#1E3A8A}\n\n/* portfolio */\n.mh-pf{max-width:880px;margin:52px auto 0;display:grid;grid-template-columns:.8fr 1.2fr;gap:20px}\n@media(max-width:760px){.mh-pf{grid-template-columns:1fr}}\n.mh-pf-card{background:#fff;border:1px solid var(--line);border-radius:26px;padding:26px;box-shadow:0 40px 70px -40px rgba(30,58,138,.5)}\n.mh-ring{width:140px;height:140px;margin:14px auto;position:relative}\n.mh-ring svg{width:100%;height:100%;transform:rotate(-90deg)}\n.mh-ring-mid{position:absolute;inset:0;display:grid;place-items:center;text-align:center;font-weight:800;font-size:13px;color:var(--muted)}\n.mh-ev{display:flex;gap:12px;align-items:flex-start;padding:12px 0;border-top:1px solid var(--line);font-size:14px}\n.mh-ev:first-of-type{border-top:0}\n\n/* compare */\n.mh-cmp{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-top:52px;align-items:stretch}\n@media(max-width:820px){.mh-cmp{grid-template-columns:1fr}}\n.mh-cmp-a{border:2px dashed #CBD5E1;border-radius:26px;padding:30px;background:#F8FAFC}\n.mh-cmp-b{border-radius:26px;padding:2px;background:linear-gradient(135deg,#2563EB,#7C3AED,#06B6D4)}\n.mh-cmp-b>div{background:#fff;border-radius:24px;padding:30px;height:100%}\n.mh-claim{color:#94A3B8;font-style:italic;padding:12px 0;border-bottom:1px dashed #CBD5E1;display:flex;justify-content:space-between;gap:10px}\n.mh-claim:last-child{border:0}\n\n/* talent + roadmap */\n.mh-talent{max-width:760px;margin:0 auto;border:1.5px dashed #A8B6CE;border-radius:30px;padding:44px 28px;text-align:center;background:linear-gradient(180deg,#F8FAFF,#fff);position:relative;overflow:hidden}\n.mh-skel{display:flex;gap:12px;align-items:center;margin:12px auto 0;max-width:420px;filter:blur(3px);opacity:.7}\n.mh-skel i{display:block;height:12px;border-radius:99px;background:#CBD5E1}\n.mh-road{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-top:52px}\n@media(max-width:760px){.mh-road{grid-template-columns:1fr}}\n.mh-road-card{border:1px solid var(--line);border-radius:24px;padding:28px;background:#fff}\n.mh-road-card li{display:flex;align-items:center;gap:12px;padding:10px 0;font-weight:500}\n\n/* cta + footer */\n.mh-cta{position:relative;overflow:hidden;border-radius:34px;padding:84px 24px;text-align:center;color:#fff;background:linear-gradient(135deg,#1D4ED8,#5B21B6)}\n.mh-cta h2{font-size:clamp(2rem,4.2vw,3.2rem);letter-spacing:-.03em;font-weight:800;line-height:1.1;position:relative}\n.mh-cta p{color:#D6E0FF;margin:16px auto 32px;max-width:520px;font-size:18px;position:relative}\n.mh-cta .mh-btn{position:relative}\n.mh-footer{background:#070E1A;color:#94A3B8;padding:48px 0}\n.mh-foot-in{display:flex;justify-content:space-between;gap:24px;flex-wrap:wrap;align-items:center}\n.mh-foot-links{display:flex;flex-wrap:wrap;gap:8px 22px}\n.mh-foot-links a{font-size:14px;transition:color .2s}\n.mh-foot-links a:hover{color:#fff}\n\n/* keyframes */\n@keyframes mh-shine{to{background-position:220% center}}\n@keyframes mh-drift{0%,100%{transform:translate(0,0) scale(1)}50%{transform:translate(40px,-30px) scale(1.1)}}\n@keyframes mh-bob{0%,100%{transform:translateY(0)}50%{transform:translateY(-12px)}}\n@keyframes mh-bar{0%,100%{transform:scaleY(.2)}50%{transform:scaleY(1)}}\n@keyframes mh-pulse{0%{box-shadow:0 0 0 0 rgba(16,185,129,.55)}70%{box-shadow:0 0 0 10px rgba(16,185,129,0)}100%{box-shadow:0 0 0 0 rgba(16,185,129,0)}}\n@keyframes mh-scroll{to{transform:translateX(-50%)}}\n@keyframes mh-sheen{0%,60%{left:-120%}100%{left:160%}}\n@keyframes mh-fill{from{width:0}to{width:100%}}\n@media(prefers-reduced-motion:reduce){.mh *,.mh *::before,.mh *::after{animation:none!important;transition:none!important}}\n","shared.tsx":"'use client'\n\nimport { useEffect, useRef, useState, type ReactNode, type MouseEvent } from 'react'\nimport { animate, motion, useInView, useReducedMotion } from 'framer-motion'\n\nexport type CtaProps = { onAuth: () => void }\n\nexport function Reveal({ children, delay = 0, className }: { children: ReactNode; delay?: number; className?: string }) {\n  const reduce = useReducedMotion()\n  if (reduce) return <div className={className}>{children}</div>\n  return (\n    <motion.div\n      className={className}\n      initial={{ opacity: 0, y: 28 }}\n      whileInView={{ opacity: 1, y: 0 }}\n      viewport={{ once: true, margin: '-70px' }}\n      transition={{ duration: 0.6, delay, ease: [0.22, 1, 0.36, 1] }}\n    >\n      {children}\n    </motion.div>\n  )\n}\n\nexport function PreviewBadge({ label = 'Example preview' }: { label?: string }) {\n  return <span className=\"mh-badge mh-b-preview\">{label}</span>\n}\n\nconst STATUS = { live: ['Live', 'mh-b-live'], partial: ['Basic version live', 'mh-b-live'], soon: ['Coming soon', 'mh-b-soon'], planned: ['Planned', 'mh-b-planned'] } as const\nexport function StatusBadge({ status }: { status: keyof typeof STATUS }) {\n  return <span className={`mh-badge ${STATUS[status][1]}`}>{STATUS[status][0]}</span>\n}\n\nexport function SectionHeader({ eyebrow, title, description }: { eyebrow?: string; title: ReactNode; description?: string }) {\n  return (\n    <Reveal className=\"mh-head\">\n      {eyebrow && <span className=\"mh-eyebrow\">{eyebrow}</span>}\n      <h2 className=\"mh-h2\">{title}</h2>\n      {description && <p className=\"mh-lead\">{description}</p>}\n    </Reveal>\n  )\n}\n\nexport function GlowCard({ children, className = '' }: { children: ReactNode; className?: string }) {\n  const move = (e: MouseEvent<HTMLDivElement>) => {\n    const r = e.currentTarget.getBoundingClientRect()\n    e.currentTarget.style.setProperty('--mx', `${e.clientX - r.left}px`)\n    e.currentTarget.style.setProperty('--my', `${e.clientY - r.top}px`)\n  }\n  return (\n    <div className={`mh-glow ${className}`} onMouseMove={move}>\n      {children}\n    </div>\n  )\n}\n\nexport function Waveform({ bars = 30 }: { bars?: number }) {\n  return (\n    <div className=\"mh-wave\" aria-hidden=\"true\">\n      {Array.from({ length: bars }).map((_, i) => (\n        <i key={i} style={{ animationDelay: `${(i % 10) * 0.11}s`, animationDuration: `${0.9 + (i % 5) * 0.15}s` }} />\n      ))}\n    </div>\n  )\n}\n\nexport function Meter({ label, value }: { label?: string; value: number }) {\n  const reduce = useReducedMotion()\n  return (\n    <div className=\"mh-meter\">\n      {label && <div className=\"mh-meter-top\"><span>{label}</span></div>}\n      <div className=\"mh-meter-bar\">\n        {reduce ? (\n          <i style={{ width: `${value}%` }} />\n        ) : (\n          <motion.i initial={{ width: 0 }} whileInView={{ width: `${value}%` }} viewport={{ once: true }} transition={{ duration: 0.9, ease: 'easeOut' }} />\n        )}\n      </div>\n    </div>\n  )\n}\n\nexport function CountUp({ to, decimals = 0, duration = 1.2 }: { to: number; decimals?: number; duration?: number }) {\n  const ref = useRef<HTMLSpanElement>(null)\n  const inView = useInView(ref, { once: true })\n  const reduce = useReducedMotion()\n  const [v, setV] = useState(0)\n  useEffect(() => {\n    if (!inView || reduce) return\n    const c = animate(0, to, { duration, ease: 'easeOut', onUpdate: setV })\n    return () => c.stop()\n  }, [inView, reduce, to, duration])\n  return <span ref={ref}>{(reduce ? to : v).toFixed(decimals)}</span>\n}\n\nexport function StaggerItem({ children, i = 0 }: { children: ReactNode; i?: number }) {\n  const reduce = useReducedMotion()\n  if (reduce) return <li>{children}</li>\n  return (\n    <motion.li initial={{ opacity: 0, x: -14 }} whileInView={{ opacity: 1, x: 0 }} viewport={{ once: true, margin: '-40px' }} transition={{ duration: 0.4, delay: i * 0.08 }}>\n      {children}\n    </motion.li>\n  )\n}\n"}

const root = process.cwd()
const target = path.join(root, 'src', 'components', 'marketing')
const log = (m) => console.log(m)
const stamp = new Date().toISOString().replace(/[:.]/g, '-')
const bdir = path.join(os.homedir(), 'mmi-backups')

if (!fs.existsSync(path.join(root, 'package.json')) || !fs.existsSync(path.join(root, 'src'))) {
  console.error('ERROR: run this from your project root (needs package.json and src/).')
  process.exit(1)
}
fs.mkdirSync(bdir, { recursive: true })

// 1. Backup
if (fs.existsSync(target)) { fs.cpSync(target, path.join(bdir, 'marketing-' + stamp), { recursive: true }); log('Backed up marketing files to ' + bdir) }

// 2. Dependencies
const pkg = JSON.parse(fs.readFileSync(path.join(root, 'package.json'), 'utf8'))
const deps = { ...pkg.dependencies, ...pkg.devDependencies }
let anim = 'framer-motion'
if (!deps['framer-motion'] && deps['motion']) anim = 'motion/react'
if (!deps['framer-motion'] && !deps['motion']) log('WARNING: framer-motion missing. Run: npm i framer-motion')
if (!deps['lucide-react']) log('WARNING: lucide-react missing. Run: npm i lucide-react')

// 3. Write components
fs.mkdirSync(target, { recursive: true })
for (const [name, content] of Object.entries(FILES)) {
  const out = anim === 'framer-motion' ? content : content.replaceAll("from 'framer-motion'", "from '" + anim + "'")
  fs.writeFileSync(path.join(target, name), out)
}
const retired = path.join(target, 'VoiceInterviewSection.tsx')
if (fs.existsSync(retired)) fs.rmSync(retired)
log('Wrote ' + Object.keys(FILES).length + ' files')

// 4. Logo (keep existing logo.ts if it already has one)
const logoFile = path.join(target, 'logo.ts')
const keep = fs.existsSync(logoFile) && /LOGO_SRC: string \| null = "/.test(fs.readFileSync(logoFile, 'utf8'))
if (!keep) {
  const pub = path.join(root, 'public')
  let logo = null
  if (fs.existsSync(pub)) { const hit = fs.readdirSync(pub).find((f) => /logo/i.test(f) && /\.(png|svg|webp|jpe?g)$/i.test(f)); if (hit) logo = '/' + hit }
  if (!logo) for (const cand of ['icon.png', 'icon.svg']) {
    const p = path.join(root, 'src', 'app', cand)
    if (fs.existsSync(p)) { fs.mkdirSync(pub, { recursive: true }); fs.copyFileSync(p, path.join(pub, 'mmi-logo' + path.extname(cand))); logo = '/mmi-logo' + path.extname(cand); break }
  }
  fs.writeFileSync(logoFile, 'export const LOGO_SRC: string | null = ' + JSON.stringify(logo) + '\n')
  log('Logo: ' + (logo || 'none, using text mark'))
} else log('Logo setting kept.')

// 5. Duplicate header fix: page.tsx must not render <MarketingNav> itself
const pagePath = path.join(root, 'src', 'app', 'page.tsx')
if (fs.existsSync(pagePath)) {
  let src = fs.readFileSync(pagePath, 'utf8')
  const jsx = src.match(/[ \t]*<MarketingNav\b[\s\S]*?\/>[ \t]*\n?/)
  if (jsx) {
    fs.copyFileSync(pagePath, path.join(bdir, 'page.tsx.' + stamp + '.bak'))
    log('\nDUPLICATE HEADER: page.tsx renders <MarketingNav> directly, on top of the one inside GuestHomepage.')
    log('Removing this from page.tsx:\n' + jsx[0].trimEnd())
    src = src.replace(jsx[0], '')
    src = src.replace(/^import MarketingNav.*\n/m, '')
    src = src.replace(/[ \t]*\{[^{}\n]*&&\s*\(\s*\)\s*\}[ \t]*\n?/g, '').replace(/[ \t]*\{[^{}\n]*&&\s*\}[ \t]*\n?/g, '')
    fs.writeFileSync(pagePath, src)
    log('Backup of the old page.tsx: ' + path.join(bdir, 'page.tsx.' + stamp + '.bak'))
  } else {
    log('\nNo direct <MarketingNav> found in page.tsx. If you still see two headers, run: grep -n "Nav\\|<header" src/app/page.tsx and paste the result.')
  }
}
log('\nDone. Restart the dev server (Ctrl+C, npm run dev) and hard-refresh with Cmd+Shift+R.')
